# Find the names of students who did NOT take any courses from the 'Biology' department.
# We filter the 'students' collection. For each student, we check their 'take' (courses taken).
# We use HASNOT to ensure that none of their taken courses are from the 'Biology' department.
students_no_biology_courses = students.WHERE(
    HASNOT(take.WHERE(
        course.dept_name == 'Biology'
    )) == 1
).CALCULATE(
    student_name=name
)

bike_most_traveled_in_zip = trips.WHERE(
    zip_code == 94002
).PARTITION(
    name="bike_trips_group",
    by=bike_id
).CALCULATE(
    bike_id = bike_id,
    num_trips = COUNT(trips)
).TOP_K(1, by=num_trips.DESC()).CALCULATE(bike_id=bike_id)

drivers_in_both_races = formula_1.result.PARTITION(
    name="driver_race_entries", by=driverid
).WHERE(
    (HAS(driver_race_entries.WHERE(race.name == "Australian Grand Prix")) > 0) &
    (HAS(driver_race_entries.WHERE(race.name == "Chinese Grand Prix")) > 0)
).CALCULATE(
    driver_id=driverid,
    forename=MIN(driver_race_entries.driver.forename)
)

most_enrolled_course_name = Courses.CALCULATE(
    course_name_aliased=course_name,
    num_students_enrolled=COUNT(student_enrolment_course.student_course_id)
).TOP_K(1, by=(num_students_enrolled.DESC(), course_name_aliased.DESC())
).CALCULATE(course_name_result=course_name_aliased)

global_average_savings = GRAPH.CALCULATE(
    avg_savings_balance=AVG(SAVINGS.balance)
)

result = ACCOUNTS.WHERE(
    ACCOUNTS.saving.balance > global_average_savings.SINGULAR().avg_savings_balance
).CALCULATE(
    account_name=name,
    total_balance=ACCOUNTS.checkings.balance + ACCOUNTS.saving.balance
)

most_common_apartment_type_code = apartment.WHERE(
    bathroom_count > 1
).PARTITION(
    name="apartment_types_group", by=apt_type_code
).CALCULATE(
    # Select the apt_type_code (partition key) and count apartments within each group
    apt_type_code=apt_type_code,
    num_apartments=COUNT(apartment)
).TOP_K(
    1, by=(num_apartments.DESC(), apt_type_code.DESC()) # Tie-breaking: sort by count DESC, then apt_type_code DESC for 'Flat'
).CALCULATE(
    apt_type_code
)

ships_without_captains = Ship.WHERE(
    HASNOT(captains)
).CALCULATE(
    Name=name,
    Class=class
)
